import path from "path"
import { fileURLToPath } from "url";
import { unionConfigsType } from "./types/main.type";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);




function compareVersions(v1 : string, v2 : string) {
    const a = String(v1 ?? "0").split(".");
    const b = String(v2 ?? "0").split(".");

    const maxLength = Math.max(a.length, b.length);

    for (let i = 0; i < maxLength; i++) {
        const num1 = Number(a[i] || 0);
        const num2 = Number(b[i] || 0);

        if (num1 > num2) {
            return 1
        }

        if (num2 > num1) {
            return -1;
        }
    }
    return 0;
};  

function shouldUpdate(latest : unionConfigsType , cached : unionConfigsType, key : string) {
    // if (latest && latest["dev-mode"] === true) return true;

    const lv = latest && latest["api-global-version"];
    const cv = cached &&  cached["api-global-version"];

    if (lv == null || cv == null) {
        return JSON.stringify(latest) !== JSON.stringify(cached);
    }

    return compareVersions(lv, cv) === 1 || JSON.stringify(latest) !== JSON.stringify(cached);
};






export { shouldUpdate,compareVersions }